#!/usr/bin/env node
/**
 * tests/adversarial-m4-deep-challenger.js
 * 
 * Deep Empirical Adversarial Verification Suite for Milestone 4 Iteration 2
 * Agent: challenger_m4_gen2_2
 * Role: Critic & Specialist
 */

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// 1. Resolve JSDOM
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved.');
      process.exit(1);
    }
  }
}

const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m',
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureList = [];

async function check(testName, fn) {
  totalChecks++;
  const idStr = totalChecks.toString().padStart(2, '0');
  const label = `[DEEP-M4-${idStr}] ${testName}`;
  const start = Date.now();
  try {
    await fn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    failureList.push({ label, error: err.message, stack: err.stack });
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label}`);
    console.log(`    ${C.red}Error: ${err.message}${C.reset}`);
  }
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function installScrollAndLayoutMocks(window) {
  window.Element.prototype.scrollIntoView = function (options) {
    this._lastScrollIntoView = options || true;
  };

  window.Element.prototype.scrollTo = function (x, y) {
    if (typeof x === 'object') {
      this.scrollLeft = x.left !== undefined ? x.left : (this.scrollLeft || 0);
      this.scrollTop = x.top !== undefined ? x.top : (this.scrollTop || 0);
      this._lastScrollBehavior = x.behavior || 'auto';
    } else {
      this.scrollLeft = x !== undefined ? x : (this.scrollLeft || 0);
      this.scrollTop = y !== undefined ? y : (this.scrollTop || 0);
    }
  };

  function makeRect(left, top, width, height) {
    return {
      left: left, top: top, width: width, height: height,
      right: left + width, bottom: top + height,
      x: left, y: top
    };
  }

  window.Element.prototype.getBoundingClientRect = function () {
    if (this.style.display === 'none') return makeRect(0, 0, 0, 0);

    if (this.classList.contains('key-btn')) {
      var row = this.closest('.keyboard-row');
      var rowIdx = row && row.parentElement ? Array.from(row.parentElement.children).indexOf(row) : 0;
      var colIdx = row ? Array.from(row.children).indexOf(this) : 0;
      var width = this.classList.contains('key-action') ? (this.getAttribute('data-key') === 'SPACE' ? 240 : 120) : 56;
      return makeRect(96 + colIdx * 70, 180 + rowIdx * 68, width, 56);
    }

    if (this.classList.contains('card-poster')) {
      return makeRect(96, 680, 264, 396);
    }

    if (this.classList.contains('card-episode')) {
      return makeRect(96, 560, 320, 180);
    }

    if (this.classList.contains('filter-pill')) {
      return makeRect(96, 120, 100, 40);
    }

    return makeRect(0, 0, 100, 50);
  };
}

function createHarness(options) {
  options = options || {};
  var mockRoutes = options.mockRoutes || {};

  var htmlPath = path.resolve(__dirname, '../app/index.html');
  var html = fs.readFileSync(htmlPath, 'utf8');

  var dom = new JSDOM(html, {
    url: 'http://localhost:8088/',
    runScripts: 'outside-only'
  });

  var window = dom.window;
  installScrollAndLayoutMocks(window);

  window._fetchCalls = [];
  window.fetch = function (url, reqOptions) {
    window._fetchCalls.push({ url: url, options: reqOptions });

    for (var route in mockRoutes) {
      if (url.indexOf(route) !== -1) {
        var handler = mockRoutes[route];
        var res = typeof handler === 'function' ? handler(url, reqOptions) : handler;

        if (res && res._delayMs) {
          return new Promise(function (resolve) {
            setTimeout(function () {
              resolve({
                ok: !res._error,
                status: res._error ? 500 : 200,
                statusText: res._error ? 'Server Error' : 'OK',
                json: function () {
                  return res._error ? Promise.reject(new Error('Server Error')) : Promise.resolve(JSON.parse(JSON.stringify(res.data || res)));
                }
              });
            }, res._delayMs);
          });
        }

        if (res && res._error) {
          return Promise.resolve({
            ok: false,
            status: 500,
            statusText: 'Internal Error',
            json: function () { return Promise.reject(new Error('Internal Error')); }
          });
        }

        return Promise.resolve({
          ok: true,
          status: 200,
          statusText: 'OK',
          json: function () { return Promise.resolve(JSON.parse(JSON.stringify(res))); }
        });
      }
    }

    return Promise.resolve({
      ok: false,
      status: 404,
      statusText: 'Not Found',
      json: function () { return Promise.resolve({ error: true }); }
    });
  };

  var configPath = path.resolve(__dirname, '../app/js/config.js');
  var navPath = path.resolve(__dirname, '../app/js/spatial-nav.js');
  var tmdbPath = path.resolve(__dirname, '../app/js/tmdb.js');
  var homePath = path.resolve(__dirname, '../app/js/views/home.js');
  var catalogPath = path.resolve(__dirname, '../app/js/views/catalog.js');
  var searchPath = path.resolve(__dirname, '../app/js/views/search.js');
  var detailsPath = path.resolve(__dirname, '../app/js/views/details.js');
  var appPath = path.resolve(__dirname, '../app/js/app.js');

  window.eval(fs.readFileSync(configPath, 'utf8'));
  window.eval(fs.readFileSync(navPath, 'utf8'));
  window.eval(fs.readFileSync(tmdbPath, 'utf8'));
  window.eval(fs.readFileSync(homePath, 'utf8'));
  window.eval(fs.readFileSync(catalogPath, 'utf8'));
  window.eval(fs.readFileSync(searchPath, 'utf8'));
  window.eval(fs.readFileSync(detailsPath, 'utf8'));
  window.eval(fs.readFileSync(appPath, 'utf8'));

  if (window.CinejoyApp && typeof window.CinejoyApp.init === 'function') {
    window.CinejoyApp.init();
  }

  return {
    dom: dom,
    window: window,
    document: window.document,
    app: window.CinejoyApp,
    nav: window.SpatialNav,
    tmdb: window.TmdbClient,
    home: window.HomeViewController,
    movies: window.MoviesViewController,
    series: window.SeriesViewController,
    search: window.SearchViewController,
    details: window.DetailsViewController
  };
}

function generateMockCards(count, type, prefix) {
  var list = [];
  for (var i = 0; i < count; i++) {
    list.push({
      id: 8000 + i,
      title: `${prefix} ${i + 1}`,
      name: `${prefix} ${i + 1}`,
      media_type: type,
      poster_path: `/mock_${i}.jpg`,
      vote_average: 8.5,
      release_date: '2024-05-15'
    });
  }
  return list;
}

async function runDeepStressSuite() {
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}${C.cyan}  Milestone 4 Iteration 2 - Deep Adversarial Race & Trap Verification    ${C.reset}`);
  console.log(`${C.bold}${C.cyan}========================================================================${C.reset}\n`);

  // -------------------------------------------------------------------------
  // TEST SUITE 1: ADV-M4-06 & ADV-M4-07 DEEP SEARCH RACES
  // -------------------------------------------------------------------------
  console.log(`${C.bold}${C.magenta}▶ SUITE 1: Deep Search Asynchronous Race Verification${C.reset}`);

  await check('ADV-M4-06 Out-of-Order: Triple Cascading Race (Q1: 500ms, Q2: 250ms, Q3: 40ms)', async function () {
    var h = createHarness({
      initialRoute: 'search',
      mockRoutes: {
        '/search/multi': function (url) {
          if (url.indexOf('QUERY1') !== -1) {
            return { _delayMs: 500, data: { page: 1, results: [{ id: 101, title: 'TITLE_1', media_type: 'movie' }] } };
          }
          if (url.indexOf('QUERY2') !== -1) {
            return { _delayMs: 250, data: { page: 1, results: [{ id: 102, title: 'TITLE_2', media_type: 'movie' }] } };
          }
          if (url.indexOf('QUERY3') !== -1) {
            return { _delayMs: 40, data: { page: 1, results: [{ id: 103, title: 'TITLE_3', media_type: 'movie' }] } };
          }
          return { page: 1, results: [] };
        }
      }
    });
    h.app.switchView('search');

    // Trigger Q1 (fires after 300ms debounce, finishes at 800ms)
    h.search.query = 'QUERY1';
    h.search.scheduleSearch();
    await sleep(320); // Q1 is now in flight

    // Trigger Q2 (fires after 300ms debounce, finishes at 320 + 300 + 250 = 870ms)
    h.search.query = 'QUERY2';
    h.search.scheduleSearch();
    await sleep(320); // Q2 is now in flight

    // Trigger Q3 (fires after 300ms debounce, finishes at 640 + 300 + 40 = 980ms)
    h.search.query = 'QUERY3';
    h.search.scheduleSearch();

    // Wait until Q3 debounce fires and resolves (300 + 40 + 50 = 390ms)
    await sleep(400);

    var grid = h.document.getElementById('search-results-grid');
    var titleQ3 = grid.querySelector('.card-poster')?.getAttribute('data-title');
    assert.strictEqual(titleQ3, 'TITLE_3', 'Q3 must render its results promptly');

    // Wait 600ms more to let any lingering delayed responses (Q1 or Q2) arrive
    await sleep(600);

    var finalTitle = grid.querySelector('.card-poster')?.getAttribute('data-title');
    assert.strictEqual(finalTitle, 'TITLE_3', 'Neither Q1 nor Q2 should ever overwrite Q3 results');
  });

  await check('ADV-M4-06 Out-of-Order: Stale 500 Error Race (Q1: 500ms Error, Q2: 50ms Success)', async function () {
    var h = createHarness({
      initialRoute: 'search',
      mockRoutes: {
        '/search/multi': function (url) {
          if (url.indexOf('ERR_QUERY') !== -1) {
            return { _delayMs: 400, _error: true };
          }
          if (url.indexOf('GOOD_QUERY') !== -1) {
            return { _delayMs: 50, data: { page: 1, results: [{ id: 104, title: 'GOOD_RESULT', media_type: 'movie' }] } };
          }
          return { page: 1, results: [] };
        }
      }
    });
    h.app.switchView('search');

    h.search.query = 'ERR_QUERY';
    h.search.scheduleSearch();
    await sleep(320); // ERR_QUERY in flight

    h.search.query = 'GOOD_QUERY';
    h.search.scheduleSearch();
    await sleep(400); // GOOD_QUERY finished

    var grid = h.document.getElementById('search-results-grid');
    var currentTitle = grid.querySelector('.card-poster')?.getAttribute('data-title');
    assert.strictEqual(currentTitle, 'GOOD_RESULT', 'GOOD_QUERY must be rendered');

    // Wait for ERR_QUERY to fail at 320 + 400 = 720ms
    await sleep(450);

    // Verify error state did NOT overwrite good result
    var errorEl = grid.querySelector('.search-error-state');
    assert.strictEqual(errorEl, null, 'Stale 500 error must NOT render error state over active good query');
    var finalTitle = grid.querySelector('.card-poster')?.getAttribute('data-title');
    assert.strictEqual(finalTitle, 'GOOD_RESULT', 'Good result must remain intact');
  });

  await check('ADV-M4-07 Clear Race: Clear Query In-Flight Followed by Immediate Retype', async function () {
    var h = createHarness({
      initialRoute: 'search',
      mockRoutes: {
        '/search/multi': function (url) {
          if (url.indexOf('FIRST_SEARCH') !== -1) {
            return { _delayMs: 300, data: { page: 1, results: [{ id: 105, title: 'FIRST_TITLE', media_type: 'movie' }] } };
          }
          if (url.indexOf('SECOND_SEARCH') !== -1) {
            return { _delayMs: 50, data: { page: 1, results: [{ id: 106, title: 'SECOND_TITLE', media_type: 'movie' }] } };
          }
          return { page: 1, results: [] };
        }
      }
    });
    h.app.switchView('search');

    h.search.query = 'FIRST_SEARCH';
    h.search.scheduleSearch();
    await sleep(320); // in flight

    // User hits CLEAR
    var clearBtn = h.document.querySelector('.key-btn[data-key="CLEAR"]');
    clearBtn.click();
    assert.strictEqual(h.search.query, '');

    // Now user types SECOND_SEARCH immediately
    h.search.query = 'SECOND_SEARCH';
    h.search.scheduleSearch();

    // Wait 400ms for SECOND_SEARCH to resolve
    await sleep(400);
    var grid = h.document.getElementById('search-results-grid');
    var title = grid.querySelector('.card-poster')?.getAttribute('data-title');
    assert.strictEqual(title, 'SECOND_TITLE', 'SECOND_SEARCH must render');

    // Wait 300ms more for FIRST_SEARCH to arrive
    await sleep(300);
    var finalTitle = grid.querySelector('.card-poster')?.getAttribute('data-title');
    assert.strictEqual(finalTitle, 'SECOND_TITLE', 'FIRST_SEARCH must not overwrite SECOND_SEARCH');
  });

  // -------------------------------------------------------------------------
  // TEST SUITE 2: ADV-M4-16 & ADV-M4-17 TV SHOW SEASON RACES
  // -------------------------------------------------------------------------
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 2: TV Show Season Switching & Out-Of-Order Race Verification${C.reset}`);

  await check('ADV-M4-16/17 Rapid Season Hopping (1 -> 2 -> 3 -> 2 with Staggered Latency)', async function () {
    var h = createHarness({
      initialRoute: 'details',
      mockRoutes: {
        '/tv/99999/season/1': { _delayMs: 400, data: { id: 1, season_number: 1, episodes: [{ id: 11, name: 'S1E1', episode_number: 1 }] } },
        '/tv/99999/season/2': { _delayMs: 150, data: { id: 2, season_number: 2, episodes: [{ id: 21, name: 'S2E1', episode_number: 1 }, { id: 22, name: 'S2E2', episode_number: 2 }] } },
        '/tv/99999/season/3': { _delayMs: 300, data: { id: 3, season_number: 3, episodes: [{ id: 31, name: 'S3E1', episode_number: 1 }] } }
      }
    });

    h.app.openDetails({ id: 99999, type: 'tv', title: 'Test Show' });
    await sleep(50);

    var bar = h.document.querySelector('.season-selector-bar');
    var s1 = bar.querySelector('.season-pill[data-season="1"]');
    var s2 = bar.querySelector('.season-pill[data-season="2"]');
    var s3 = bar.querySelector('.season-pill[data-season="3"]');

    // Rapidly click S1 -> S2 -> S3 -> S2
    s1.click();
    s2.click();
    s3.click();
    s2.click(); // S2 is active!
    assert.strictEqual(h.details.activeSeason, 2);

    // Wait 500ms for all responses to finish
    await sleep(500);

    var rail = h.document.getElementById('details-episodes-rail');
    var epCards = rail.querySelectorAll('.card-episode');
    assert.strictEqual(epCards.length, 2, 'Active Season 2 must have exactly 2 episodes');
    assert.strictEqual(epCards[0].getAttribute('data-season'), '2', 'Rendered season must match active season 2');
    assert.strictEqual(epCards[0].getAttribute('data-title'), 'S2E1');
  });

  await check('ADV-M4-16/17 Details View Navigation Switch Race (Show A Season in-flight, navigate to Show B)', async function () {
    var h = createHarness({
      initialRoute: 'details',
      mockRoutes: {
        '/tv/10001/season/1': { _delayMs: 400, data: { id: 1, season_number: 1, episodes: [{ id: 101, name: 'Show A S1', episode_number: 1 }] } },
        '/tv/10002/season/1': { _delayMs: 50, data: { id: 1, season_number: 1, episodes: [{ id: 201, name: 'Show B S1', episode_number: 1 }] } }
      }
    });

    // Open Show A (id: 10001)
    h.app.openDetails({ id: 10001, type: 'tv', title: 'Show A' });
    await sleep(20);

    // User navigates away to Show B (id: 10002)
    h.app.openDetails({ id: 10002, type: 'tv', title: 'Show B' });
    await sleep(100); // Show B resolves (50ms)

    var rail = h.document.getElementById('details-episodes-rail');
    var titleBefore = rail.querySelector('.card-episode')?.getAttribute('data-title');
    assert.strictEqual(titleBefore, 'Show B S1', 'Show B episodes must render');

    // Wait 400ms for Show A Season 1 to resolve
    await sleep(400);

    // Show A response must NOT overwrite Show B episodes
    var titleAfter = rail.querySelector('.card-episode')?.getAttribute('data-title');
    assert.strictEqual(titleAfter, 'Show B S1', 'Show A delayed season response must NOT overwrite Show B episodes');
  });

  // -------------------------------------------------------------------------
  // TEST SUITE 3: ADV-M4-24 CATALOG FILTER SWITCHING RACE
  // -------------------------------------------------------------------------
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 3: Catalog Filter Switching Race Verification${C.reset}`);

  await check('ADV-M4-24 Multi-Filter Burst (Pill 1: 300ms, Pill 2: 200ms, Pill 3: 40ms)', async function () {
    var h = createHarness({
      initialRoute: 'movies',
      mockRoutes: {
        '/discover/movie': function (url) {
          if (url.indexOf('with_genres=28') !== -1) {
            return { _delayMs: 300, data: { page: 1, results: generateMockCards(5, 'movie', 'Action') } };
          }
          if (url.indexOf('with_genres=35') !== -1) {
            return { _delayMs: 200, data: { page: 1, results: generateMockCards(5, 'movie', 'Comedy') } };
          }
          if (url.indexOf('with_genres=878') !== -1) {
            return { _delayMs: 40, data: { page: 1, results: generateMockCards(5, 'movie', 'Sci-Fi') } };
          }
          return { page: 1, results: generateMockCards(5, 'movie', 'Default') };
        }
      }
    });

    h.app.switchView('movies');
    await sleep(50);

    var filterBar = h.document.querySelector('#view-movies .filter-bar');
    var pAction = filterBar.querySelector('.filter-pill[data-genre-id="28"]');
    var pComedy = filterBar.querySelector('.filter-pill[data-genre-id="35"]');
    var pSciFi = filterBar.querySelector('.filter-pill[data-genre-id="878"]');

    // Rapid burst clicks
    pAction.click(); // 300ms
    pComedy.click(); // 200ms
    pSciFi.click();  // 40ms
    assert.strictEqual(h.movies.state.activeGenreId, 878);
    assert(pSciFi.classList.contains('active'), 'Sci-Fi pill must be visually active');

    // Wait 100ms: Sci-Fi (40ms) should have resolved and rendered
    await sleep(100);
    var grid = h.document.querySelector('#view-movies .content-grid-6col');
    var firstTitle = grid.querySelector('.card-poster')?.getAttribute('data-title');
    assert(firstTitle && firstTitle.indexOf('Sci-Fi') !== -1, 'Sci-Fi must be rendered');

    // Wait 350ms more for Comedy (200ms) and Action (300ms) to resolve
    await sleep(350);

    var finalTitle = grid.querySelector('.card-poster')?.getAttribute('data-title');
    assert(finalTitle && finalTitle.indexOf('Sci-Fi') !== -1, `Stale Action/Comedy must NOT overwrite Sci-Fi! Got: ${finalTitle}`);
    assert.strictEqual(h.movies.state.isLoading, false, 'isLoading must be false once active request completes');
  });

  // -------------------------------------------------------------------------
  // TEST SUITE 4: VIRTUAL KEYBOARD RAPID TYPING & MODAL FOCUS TRAPPING
  // -------------------------------------------------------------------------
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 4: Virtual Keyboard Rapid Typing & Focus Trapping${C.reset}`);

  await check('Virtual Keyboard: 100-Key Rapid Burst Typing Stress', async function () {
    var h = createHarness({ initialRoute: 'search' });
    h.app.switchView('search');

    var sampleKeys = ['H', 'E', 'L', 'L', 'O', 'SPACE', 'W', 'O', 'R', 'L', 'D', '1', '2', '3'];
    var expectedStr = '';

    for (var i = 0; i < 100; i++) {
      var k = sampleKeys[i % sampleKeys.length];
      if (k === 'SPACE') {
        expectedStr += ' ';
      } else {
        expectedStr += k;
      }
      var btn = h.document.querySelector(`.key-btn[data-key="${k}"]`);
      assert(btn, `Key button ${k} must exist`);
      btn.click();
    }

    assert.strictEqual(h.search.query, expectedStr, 'All 100 keys must accumulate perfectly');
    assert.strictEqual(h.document.getElementById('search-query-text').textContent, expectedStr);
  });

  await check('SpatialNav Focus Trap Integrity: Complete Boundary Perimeter Containment', async function () {
    var h = createHarness({ initialRoute: 'search' });
    h.app.switchView('search');

    assert.strictEqual(h.nav.isTrapped(), true, 'Focus trap must be active in search view');

    // Verify all 4 directional boundaries while results grid is empty
    h.search.renderResults([]);

    // 1. Move from top row UP
    var key1 = h.document.querySelector('.key-btn[data-key="1"]');
    h.nav.setFocus(key1);
    var upRes = h.nav.move('up');
    assert.strictEqual(upRes, null, 'Cannot move UP past keyboard top boundary');
    assert.strictEqual(h.nav.getCurrentFocus(), key1);

    // 2. Move from bottom row DOWN
    var spaceKey = h.document.querySelector('.key-btn[data-key="SPACE"]');
    h.nav.setFocus(spaceKey);
    var downRes = h.nav.move('down');
    assert.strictEqual(downRes, null, 'Cannot move DOWN past keyboard when results grid is empty');
    assert.strictEqual(h.nav.getCurrentFocus(), spaceKey);

    // 3. Move from leftmost column LEFT
    var keyA = h.document.querySelector('.key-btn[data-key="A"]');
    h.nav.setFocus(keyA);
    var leftRes = h.nav.move('left');
    assert.strictEqual(leftRes, null, 'Cannot move LEFT past keyboard leftmost boundary');
    assert.strictEqual(h.nav.getCurrentFocus(), keyA);

    // 4. Move from rightmost column RIGHT
    var keyL = h.document.querySelector('.key-btn[data-key="L"]');
    h.nav.setFocus(keyL);
    var rightRes = h.nav.move('right');
    assert.strictEqual(rightRes, null, 'Cannot move RIGHT past keyboard rightmost boundary');
    assert.strictEqual(h.nav.getCurrentFocus(), keyL);
  });

  await check('SpatialNav Focus Trap: Seamless Untrap on View Transition & Results Navigation', async function () {
    var h = createHarness({ initialRoute: 'search' });
    h.app.switchView('search');
    assert.strictEqual(h.nav.isTrapped(), true);

    // Populate search results
    h.search.renderResults(generateMockCards(2, 'movie', 'Result'));
    var card0 = h.document.querySelector('#search-results-grid .card-poster');
    assert(card0, 'Result card exists');

    // Focus on bottom action row and press ArrowDown
    var spaceKey = h.document.querySelector('.key-btn[data-key="SPACE"]');
    h.nav.setFocus(spaceKey);

    var ev = new h.window.KeyboardEvent('keydown', { key: 'ArrowDown', bubbles: true });
    spaceKey.dispatchEvent(ev);

    assert.strictEqual(h.nav.isTrapped(), false, 'SpatialNav must untrap when descending into results');
    assert.strictEqual(h.nav.getCurrentFocus(), card0, 'Focus moved to first card');

    // Switch view to home: SpatialNav must remain untrapped and normal navigation restored
    h.app.switchView('home');
    assert.strictEqual(h.nav.isTrapped(), false, 'Untrapped on switchView to home');
  });

  // -------------------------------------------------------------------------
  // Summary
  // -------------------------------------------------------------------------
  console.log(`\n${C.bold}========================================================================${C.reset}`);
  console.log(`${C.bold}Deep Adversarial Stress Execution Summary:${C.reset}`);
  console.log(`  Total Checks:   ${totalChecks}`);
  console.log(`  Passed Checks:  ${C.green}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:  ${failedChecks > 0 ? C.red + failedChecks + C.reset : '0'}`);
  console.log(`${C.bold}========================================================================${C.reset}\n`);

  if (failedChecks === 0) {
    console.log(`${C.green}${C.bold}✅ ALL ${totalChecks} DEEP ADVERSARIAL STRESS CHECKS PASSED (100% SUCCESS)${C.reset}\n`);
    process.exit(0);
  } else {
    console.error(`${C.red}${C.bold}❌ ${failedChecks} DEEP ADVERSARIAL CHECKS FAILED${C.reset}\n`);
    failureList.forEach(function (f) {
      console.error(`- ${f.label}: ${f.error}`);
    });
    process.exit(1);
  }
}

runDeepStressSuite().catch(function (err) {
  console.error('Unhandled fatal error in deep adversarial suite:', err);
  process.exit(1);
});

